def summarize_order(order):
    # One long function: totals, coupon, tax and the result in one place.
    subtotal = 0
    count = 0
    for item in order["items"]:
        subtotal = subtotal + item["qty"] * item["unit_cents"]
        count = count + item["qty"]
    coupon = order.get("coupon")
    discount = 0
    if coupon == "SAVE10":
        discount = subtotal * 10 // 100
    elif coupon == "FLAT500":
        if subtotal < 500:
            discount = subtotal
        else:
            discount = 500
    country = order["country"]
    if country == "DE":
        rate = 19
    elif country == "FR":
        rate = 20
    elif country == "US":
        rate = 0
    else:
        rate = 0
    taxable = subtotal - discount
    tax = taxable * rate // 100
    total = taxable + tax
    result = {}
    result["item_count"] = count
    result["subtotal_cents"] = subtotal
    result["discount_cents"] = discount
    result["tax_cents"] = tax
    result["total_cents"] = total
    return result
